interface OrderStore {
  void save(Order order);
  Order findById(OrderId id) throws OrderNotFound;
}

final class OrderService {
  private final OrderStore store;
  OrderService(OrderStore store) { this.store = store; }

  void place(Order order) {
    store.save(order);
  }
}

// Leaky: every caller must know which variant sits behind it.
interface LeakyStore {
  void save(Order order, boolean flushImmediately, int sqlTimeoutMs);
  Object rawHandle(); // forces callers to downcast
}

final class LeakyService {
  void place(LeakyStore s, Order o) {
    if (s instanceof PostgresBackedStore) {
      s.save(o, true, 5000);
    } else {
      s.save(o, false, 0);
    }
  }
}
